        updateVerification();
      });

      field.addEventListener("keydown", event => {
        if (event.key === "Backspace" && !field.value && index > 0) {
          fields[index - 1].focus();
        }

        if (event.key === "ArrowLeft" && index < fields.length - 1) {
          fields[index + 1].focus();
        }

        if (event.key === "ArrowRight" && index > 0) {
          fields[index - 1].focus();
        }
      });

      field.addEventListener("paste", event => {
        const digits = (event.clipboardData.getData("text") || "").replace(/\D/g, "").slice(0, 6);
        if (!digits) return;

        event.preventDefault();
        digits.split("").forEach((digit, digitIndex) => {
          if (fields[digitIndex]) {
            fields[digitIndex].value = digit;
            fields[digitIndex].classList.add("filled");
          }
        });

        fields[Math.min(digits.length, 6) - 1].focus();
        updateVerification();
      });
    });

    verifyButton.addEventListener("click", () => {
      if (verifyButton.disabled) return;
      status.textContent = "تم التحقق من الرمز بنجاح.";
      status.classList.remove("error");
      verifyButton.textContent = "تم التحقق";
