    resendButton.addEventListener("click", () => {
      remainingSeconds = 45;
      updateCountdown();
      timer = setInterval(updateCountdown, 1000);
      status.textContent = "تم إرسال رمز جديد.";
      status.classList.remove("error");
      fields.forEach(field => {
        field.value = "";
        field.classList.remove("filled");
      });
      updateVerification();
      fields[0].focus();
    });

    updateCountdown();
    timer = setInterval(updateCountdown, 1000);
  </script>
